'use strict';

const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const loaderFile = path.join(root, 'public', 'js', 'index-loader.js');
const outputFile = path.join(root, 'public', 'js', 'shinayuu-index-bundle.js');

function extractModulePaths(source) {
  const match = source.match(/const\s+modulePaths\s*=\s*\[([\s\S]*?)\n\s*\];/);
  if (!match) throw new Error('Could not find modulePaths in public/js/index-loader.js');
  const paths = [];
  const itemRe = /['"]([^'"]+\.js)['"]/g;
  let item;
  while ((item = itemRe.exec(match[1]))) paths.push(item[1]);
  if (!paths.length) throw new Error('Renderer module manifest is empty');
  return paths;
}

function normalizeModuleText(text) {
  return String(text || '').replace(/^\uFEFF/, '').replace(/\r\n/g, '\n');
}

function buildBundle() {
  const loaderSource = fs.readFileSync(loaderFile, 'utf8');
  const modulePaths = extractModulePaths(loaderSource);
  const chunks = [
    "'use strict';",
    '/* Generated by tools/build-renderer-bundle.js. Do not edit directly. */',
    `window.__shinayuuRendererBundleStartedAt = performance.now();`,
  ];

  for (const relativePath of modulePaths) {
    const absolutePath = path.join(root, 'public', relativePath);
    if (!fs.existsSync(absolutePath)) throw new Error(`Missing renderer module: ${relativePath}`);
    const source = normalizeModuleText(fs.readFileSync(absolutePath, 'utf8'));
    chunks.push(`\n/* ===== ${relativePath} ===== */\n${source}\n;`);
  }

  chunks.push([
    '',
    'window.__shinayuuModulesLoaded = true;',
    'window.__shinayuuRendererBundleFinishedAt = performance.now();',
    "if (typeof window.__shinayuuMarkModulesLoaded === 'function') {",
    `  window.__shinayuuMarkModulesLoaded({ total: ${modulePaths.length}, loadFailures: [], bundled: true, durationMs: window.__shinayuuRendererBundleFinishedAt - window.__shinayuuRendererBundleStartedAt });`,
    '}',
    '//# sourceURL=shinayuu-index-bundle.js',
    '',
  ].join('\n'));

  const output = chunks.join('\n');
  const previous = fs.existsSync(outputFile) ? fs.readFileSync(outputFile, 'utf8') : '';
  if (previous !== output) fs.writeFileSync(outputFile, output, 'utf8');
  console.log(`[renderer-bundle] ${modulePaths.length} modules -> ${path.relative(root, outputFile)} (${Buffer.byteLength(output)} bytes)`);
}

try {
  buildBundle();
} catch (error) {
  console.error('[renderer-bundle] failed:', error && (error.stack || error.message) || error);
  process.exitCode = 1;
}
